// Generates app/fonts.generated.ts from site.json (MaisonElva.theme.fonts), so fonts are changed by
// editing only site.json. The generated file loads each font with next/font/google, which downloads
// it at build time and serves it from this site (visitors never contact Google). Runs before `dev`
// and `build`; an unknown font or weight keeps the previous file and prints a warning.
// `"weights": "variable"` loads the variable version (any weight, e.g. font-[350]).
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const OUT = new URL("../app/fonts.generated.ts", import.meta.url);
const site = JSON.parse(readFileSync(new URL("../data/site.json", import.meta.url), "utf8"));
const fonts = site[Object.keys(site)[0]].theme.fonts;
// The list of Google Fonts (with their weights and styles) that ships with next/font.
const catalog = require("next/dist/compiled/@next/font/dist/google/font-data.json");

const errors = [];
const loaders = Object.entries(fonts).map(([key, font]) => {
  const data = catalog[font.family];
  const weights = font.weights === "variable" ? ["variable"] : font.weights.map(String);
  if (!data) {
    errors.push(`"${font.family}" (${key}) is not a Google Font - check the spelling on fonts.google.com`);
  } else {
    const missing = weights.filter((w) => !data.weights.includes(w));
    if (missing.length) errors.push(`"${font.family}" has no weight ${missing.join(", ")} (available: ${data.weights.join(", ")})`);
    if (font.italic && !data.styles.includes("italic")) errors.push(`"${font.family}" has no italic style`);
  }
  const options = {
    subsets: ["latin"],
    ...(font.weights === "variable" ? {} : { weight: weights }),
    style: font.italic ? ["normal", "italic"] : ["normal"],
    display: "swap",
    fallback: font.fallback.split(",").map((f) => f.trim().replace(/^["']|["']$/g, "")),
    variable: `--font-${key}-face`,
  };
  return { key, fn: font.family.replace(/ /g, "_"), options };
});

if (errors.length) {
  for (const e of errors) console.warn(`fonts: ${e}.`);
  if (existsSync(OUT)) {
    console.warn("fonts: keeping the previous fonts.");
    process.exit(0);
  }
  process.exit(1);
}

// next/font needs a plain object literal (unquoted keys), not JSON.
const toLiteral = (o) => `{ ${Object.entries(o).map(([k, v]) => `${k}: ${JSON.stringify(v)}`).join(", ")} }`;

const imports = [...new Set(loaders.map((l) => l.fn))].sort();
const code = `// Generated by scripts/fonts.mjs from site.json (theme.fonts) - edit site.json, not this file.
import { ${imports.join(", ")} } from "next/font/google";

${loaders.map((l) => `const ${l.key} = ${l.fn}(${toLiteral(l.options)});`).join("\n")}

/** CSS variables (--font-<key>-face) for the <html> element. */
export const fontVariables = [${loaders.map((l) => `${l.key}.variable`).join(", ")}].join(" ");
`;

if (!existsSync(OUT) || readFileSync(OUT, "utf8") !== code) {
  writeFileSync(OUT, code);
  console.log(`fonts: ${loaders.map((l) => `${l.key} = ${fonts[l.key].family}`).join(", ")}`);
}
